import Foundation

// What MS Gothic and Yu Gothic hold of U+2E80-U+FFFF, by the cmaps of
// msgothic.ttc and YuGothR.ttc in Word 16's DFonts (Word for Mac 16.113),
// as bitmaps, a bit a character from U+2E80, low bit first. Word for
// Windows sets what an embedded 仿宋_GB2312 subset lacks in the first of
// MS Gothic, Yu Gothic and Microsoft JhengHei that has it
// (`OfficeFonts.windowsSubsetFallback`). Generated; the faces' own tables,
// not an encoding's: MS Gothic holds 开 and 关, which Shift_JIS has not.
enum WindowsFallbackCovers {
    static let msGothic: Set<UInt32> = decode("")
    static let yuGothic: Set<UInt32> = decode("")

    private static func decode(_ base64: String) -> Set<UInt32> {
        guard let data = Data(base64Encoded: base64) else { return [] }
        var out = Set<UInt32>()
        for (i, byte) in data.enumerated() where byte != 0 {
            for bit in 0 ..< 8 where byte & (1 << bit) != 0 { out.insert(0x2E80 + UInt32(i * 8 + bit)) }
        }
        return out
    }
}
